from pathlib import Path
import sys
import base64, html, json

here=Path(__file__).resolve().parent
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from media import media_root
root=media_root()
manifest=json.loads((root/'slides.json').read_text())
notes=json.loads((here/'slide-notes.json').read_text())
transcript=json.loads((here/'transcript.json').read_text())
assert len(manifest)==len(notes)==42
for item,note in zip(manifest,notes):
    assert item['number']==note['n']
    item.update(note)

intro='''# Full-video analysis: All Code Is Slop (Except Mine)

Lauren Tan (poteto), AI Engineer Code Summit. Source: https://www.youtube.com/watch?v=O_zcc6Xl12g

Reviewed the complete 135-segment automatic transcript, 105 frames sampled across the full 17:31 video, and 71 detected visual transitions. Selected 42 readable captures covering the substantive slides and significant builds. Repeated pyramid highlights and UI-demo frames are grouped where they communicate the same point. Intro/outro logos and camera cuts add no setup details. Capture times below are reading positions, not exact slide-start timestamps. The downloaded MP4 is a video-only stream; the speech source used here is the complete automatic transcript, with technical names checked against slide text.

The core mechanism is a reinforcing loop: the codebase teaches agents patterns; framework APIs and machine checks constrain new work; runtime and formal verification provide feedback; human review focuses on evidence and unresolved judgment; repeated mistakes improve the environment. External triggers scale that established loop.

The talk gives enough detail to reconstruct the architecture of the process, but does not expose the complete internal configuration. Distinguish observed slide content, Lauren's reported experience, and our proposed application. In particular, model/proof validity remains scoped to its assumptions and connection to implementation.

Related source: https://github.com/cursor/plugins/tree/main/pstack

Implementation details and platform adaptations: [IMPLEMENTATION-GUIDE.md](IMPLEMENTATION-GUIDE.md).

'''
parts=[intro]
for s in manifest:
    image_path=f"../../artifacts/slides/{s['image']}"
    parts.append(f"## {s['number']:02}. {s['title']} — {s['timestamp']}\n\n[Video at capture](https://www.youtube.com/watch?v=O_zcc6Xl12g&t={s['seconds']}s) · [Full-resolution capture]({image_path})\n\n**Observed / reported:** {s['observed']}\n\n**How it works:** {s['mechanism']}\n\n**Application and limits:** {s['apply']}\n\n")
(here/'ANALYSIS.md').write_text(''.join(parts))

for s in manifest:
    s['data']='data:image/jpeg;base64,'+base64.b64encode((root/'slides'/s['image']).read_bytes()).decode()

template='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Lauren Tan — annotated video research</title>
<style>
:root{--foreground:#e5e7eb;--muted-foreground:#9ca3af;--card:#171b24;--border:#343b49;--primary:#78b9fa;--chart-1:#78b9fa;--chart-2:#b59af8;--radius:10px;--font-sans:system-ui,sans-serif;--font-mono:ui-monospace,monospace}
*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--foreground);font-family:var(--font-sans);line-height:1.55}p{margin:8px 0 14px}a{color:var(--primary)}button,select,input{font:inherit;color:var(--foreground);background:var(--card);border:1px solid var(--border);border-radius:6px;padding:8px}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--primary)}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.tabs{margin:14px 0}.tabs button[aria-selected=true]{border-color:var(--primary);color:var(--primary)}.muted,small{color:var(--muted-foreground)}.card{background:var(--card);padding:16px;border-radius:var(--radius);margin:12px 0}.panel[hidden]{display:none}#slide-image{width:100%;height:auto;display:block;border-radius:6px;background:white;margin:14px 0}#chooser{flex:1;min-width:200px;width:100%}h2{font-size:20px;margin:10px 0}h3{font-size:16px;margin:16px 0 4px}details{border-top:1px solid var(--border);padding:10px 0}summary{cursor:pointer;font-weight:600}.flow{display:grid;gap:8px}.step{background:var(--card);padding:12px 16px;border-left:3px solid var(--primary);border-radius:6px}.step b{display:block}.bar-row{display:grid;grid-template-columns:40px 1fr 75px;align-items:center;gap:8px;margin:14px 0}.track{height:24px;border-left:1px solid var(--border)}.bar{height:100%;background:var(--chart-1);border-radius:0 4px 4px 0}.bar-row strong{text-align:right;font-size:14px}.transcript-line{display:grid;grid-template-columns:48px 1fr;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)}#transcript-list{max-height:580px;overflow:auto}#filter{width:100%;margin:8px 0}#stage-control{width:100%}code{font-family:var(--font-mono);font-size:.9em}ul{padding-left:22px}li{margin:7px 0}@media(max-width:450px){.card{padding:12px}.tabs{gap:5px}.tabs button{font-size:13px;padding:7px}.bar-row{grid-template-columns:32px 1fr 65px}}
</style></head><body>
<p><strong>Her setup, reconstructed from the entire video.</strong> Explore 42 slide captures and builds, the operating loop, exact chart values, and the full transcript.</p>
<p class="muted">Complete transcript + full-video visual sampling + transition inspection. Slide times are capture positions. Our applications are labeled separately from what she shows or reports.</p>
<div class="row tabs" role="tablist" aria-label="Research views">
<button role="tab" aria-selected="true" data-tab="slides">Slides</button><button role="tab" aria-selected="false" data-tab="workflow">Setup</button><button role="tab" aria-selected="false" data-tab="metrics">Evidence</button><button role="tab" aria-selected="false" data-tab="transcript">Transcript</button></div>
<section id="slides" class="panel" role="tabpanel"><div class="row"><button id="previous" aria-label="Previous slide">←</button><select id="chooser" aria-label="Choose slide"></select><button id="next" aria-label="Next slide">→</button></div><img id="slide-image" alt=""><p><a id="video-link" target="_blank" rel="noopener">Open video at this capture ↗</a> <span class="muted" id="slide-position"></span></p><div class="card"><h2 id="slide-title"></h2><h3>What she shows or reports</h3><p id="observed"></p><h3>How it works</h3><p id="mechanism"></p><h3>How we apply it · limits</h3><p id="application"></p></div><details><summary>Coverage and source limits</summary><p>42 selected captures cover substantive slides and significant builds; repeated highlighting and the UI animation are grouped. We reviewed 105 full-video overview frames, 71 visual transitions, and all 135 automatic transcript segments. The MP4 saved for frame extraction has video only. Technical names were checked against slides; the transcript remains raw.</p><p>Dune source, CI/merge rules, private drivers, actual TLA+ specifications, Lean proofs, Bombadil properties, exact agent configuration, and cost accounting are not provided by the talk.</p></details></section>
<section id="workflow" class="panel" role="tabpanel" hidden><p><strong>The reusable unit is a maintained engineering environment.</strong> The automation layer supplies work to a loop that already produces verifiable results.</p><div class="flow"><div class="step"><b>1 · Product framework</b>Approved APIs own lifecycle, persistence, subscriptions, navigation, and platform bridges.</div><div class="step"><b>2 · Enforced constraints</b>Imports, types, linting, tests, and CI make recurring mistakes difficult to land.</div><div class="step"><b>3 · Verification surface</b>A feature map names user journeys; a reusable driver launches the real app, performs actions, observes state, and captures evidence.</div><div class="step"><b>4 · Reviewable evidence</b>Recordings, screenshots, side effects, traces, model-checking results, and proofs support specific claims.</div><div class="step"><b>5 · Feedback and automation</b>Corrections improve APIs/checks; release, issue, schedule, or alert events repeat the proven loop.</div></div><details open><summary>One portable example: offline send</summary><p>Specify enqueue, retry, cancellation, restart, and second-device behavior. Use a domain API with idempotency and platform adapters. Drive the visible journey on each platform; observe the actual committed message. Generate reconnect/cancel sequences. Model ordering races when needed. A screenshot of “sent” alone cannot establish exactly one durable message.</p></details><details><summary>Mobile, desktop, web, services</summary><p>Use platform-appropriate drivers: native UI automation on iOS/Android, browser/CDP or existing harnesses on web/Electron, OS accessibility on native desktop, HTTP on services, and PTYs on CLIs. Share feature vocabulary and domain invariants; keep platform-specific permissions, lifecycle, distribution, and device checks.</p></details><details><summary>What to build first</summary><ol><li>Make a clean checkout runnable and verify one real feature.</li><li>Replace the most common bad pattern and enforce the replacement.</li><li>Map three to five important journeys and automate evidence capture.</li><li>Add generated sequences, selected models, and performance budgets.</li><li>Automate a bounded task after the inner loop proves dependable.</li></ol></details><p><a href="https://github.com/cursor/plugins/tree/main/pstack" target="_blank" rel="noopener">Related public pstack workflows ↗</a></p></section>
<section id="metrics" class="panel" role="tabpanel" hidden><p>These are the talk's reported observations, without an independently reproduced benchmark or causal experiment.</p><label for="metric">Chart</label> <select id="metric"><option value="prs">Team merged PRs</option><option value="reverts">Reverted commits (%)</option><option value="people">Contributors</option></select><div id="chart" role="img"></div><p class="muted" id="metric-note"></p><details open><summary>Performance improved unevenly</summary><p>Cold launch: 2,304 → 1,395ms. Long-chat median typing: 8.4 → 2.9ms. Switching back to a long chat: 105 → 63ms.</p><p>Regressions include cold long-chat opening (153 → 165ms), resize (3.0 → 6.9ms), idle memory (488 → 545MiB), idle CPU (0.40 → 0.80%), and startup JS+CSS (2.0 → 7.7MB).</p><p>Hardware, repetitions, workload definitions, and benchmark procedures are not shown. The full slide is entry 35.</p></details><details><summary>The release fuzzing report is more concrete than the PR totals</summary><p>It verifies package hashes, compares with version 0.79.4, names the local backend and copied gate configuration, deduplicates findings, and distinguishes three new issues from 47 pre-existing ones. This identifies exactly what was tested. The displayed report does not itself prove the fix PRs passed or merged.</p></details></section>
<section id="transcript" class="panel" role="tabpanel" hidden><p class="muted">Raw automatic captions contain technical-name errors. Analysis uses slide-confirmed names such as Grok Bot, pstack, TLA+, and poteto.</p><input id="filter" type="search" aria-label="Search transcript" placeholder="Search all 135 segments"><div id="transcript-list"></div></section>
<script>
const slides=__SLIDES__,transcript=__TRANSCRIPT__;
const $=id=>document.getElementById(id);let position=7;
slides.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=String(s.number).padStart(2,'0')+' · '+s.timestamp+' · '+s.title;$('chooser').append(o)});
function showSlide(i){position=Math.max(0,Math.min(slides.length-1,i));const s=slides[position];$('chooser').value=position;$('slide-image').src=s.data;$('slide-image').alt=s.title+' — video capture '+s.timestamp;$('slide-title').textContent=s.title;$('observed').textContent=s.observed;$('mechanism').textContent=s.mechanism;$('application').textContent=s.apply;$('video-link').href='https://www.youtube.com/watch?v=O_zcc6Xl12g&t='+s.seconds+'s';$('slide-position').textContent=' · '+(position+1)+' / '+slides.length;$('previous').disabled=position===0;$('next').disabled=position===slides.length-1;}
$('previous').onclick=()=>showSlide(position-1);$('next').onclick=()=>showSlide(position+1);$('chooser').onchange=e=>showSlide(Number(e.target.value));
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.tab)});
const metrics={prs:{values:[809,1984,4203,5648,10926],label:'Team merged PRs',note:'June–October, 23,570 total. The spoken 11,000 is rounded. PR size, task mix, cost, and outcomes are not supplied.'},reverts:{values:[.98,.61,.47,.48,.47],label:'Percentage of commits reverted',note:'The slide denominator is commits, not PRs. This is not an overall defect rate and excludes forward fixes unless they are counted as reverts.'},people:{values:[15,48,95,163,227],label:'Contributors',note:'Team growth is a confounder when interpreting total PR growth. October spans both core and drive-by contributors.'}};
function chart(){const m=metrics[$('metric').value],max=Math.max(...m.values);$('chart').replaceChildren();$('chart').setAttribute('aria-label',m.label+': '+m.values.join(', '));m.values.forEach((v,i)=>{const row=document.createElement('div');row.className='bar-row';const month=document.createElement('span');month.textContent=['Jun','Jul','Aug','Sep','Oct'][i];const track=document.createElement('div');track.className='track';const bar=document.createElement('div');bar.className='bar';bar.style.width=(v/max*100)+'%';track.append(bar);const value=document.createElement('strong');value.textContent=$('metric').value==='reverts'?v.toFixed(2)+'%':v.toLocaleString();row.append(month,track,value);$('chart').append(row)});$('metric-note').textContent=m.note;}$('metric').onchange=chart;
function showTranscript(){const query=$('filter').value.toLowerCase();$('transcript-list').replaceChildren();transcript.filter(s=>s.text.toLowerCase().includes(query)||s.time.includes(query)).forEach(s=>{const row=document.createElement('div');row.className='transcript-line';const a=document.createElement('a'),p=document.createElement('span');const sec=s.time.split(':').reduce((a,n)=>a*60+Number(n),0);a.href='https://www.youtube.com/watch?v=O_zcc6Xl12g&t='+sec+'s';a.target='_blank';a.rel='noopener';a.textContent=s.time;p.textContent=s.text;row.append(a,p);$('transcript-list').append(row)})}$('filter').oninput=showTranscript;
showSlide(position);chart();showTranscript();
</script></body></html>'''
data=json.dumps(manifest).replace('<','\\u003c')
text=json.dumps(transcript).replace('<','\\u003c')
page=template.replace('__SLIDES__',data).replace('__TRANSCRIPT__',text)
(root/'annotated-viewer.html').write_text(page)
for s in manifest:
    s.pop('data')
assets='<div hidden>'+''.join(f'<img id="asset-{s["number"]}" src="slides/{s["image"]}" alt="">' for s in manifest)+'</div>'
inline=template.replace('__SLIDES__',json.dumps(manifest).replace('<','\\u003c')).replace('__TRANSCRIPT__',text)
inline=inline.replace('<script>',assets+'<script>').replace("$('slide-image').src=s.data", "$('slide-image').src=document.getElementById('asset-'+s.number).src")
(root/'inline-viewer.html').write_text(inline)
for name in ['ANALYSIS.md','IMPLEMENTATION-GUIDE.md','transcript.json','slide-notes.json']:
    (root/name).write_bytes((here/name).read_bytes())
print(f'Wrote analysis, implementation guide, and viewer ({len(page)/1024/1024:.1f} MiB).')
